import 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../../../core/routing/app_router.dart';import '../../../providers/auth_provider.dart';
class SplashScreen extends StatefulWidget{const SplashScreen({super.key});@override State<SplashScreen> createState()=>_SplashScreenState();}
class _SplashScreenState extends State<SplashScreen>{@override void initState(){super.initState();WidgetsBinding.instance.addPostFrameCallback((_){if(!mounted)return;final u=context.read<AuthProvider>().firebaseUser;Navigator.pushReplacementNamed(context,u!=null&&u.emailVerified?AppRouter.home:AppRouter.login);});}@override Widget build(BuildContext context)=>const Scaffold(body:Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.apartment,size:64),SizedBox(height:12),Text('Campus Incident Reporter'),CircularProgressIndicator()])));}
